const ts = String(Math.floor(Date.now() / 1000));
return [{
  json: {
    messages: [{
      from: '27123456789',
      id: 'wamid.HBgM_mock',
      timestamp: ts,
      type: 'text',
      text: { body: 'Hi, what are your opening hours this Saturday?' }
    }],
    contacts: [{ profile: { name: 'Demo Customer' }, wa_id: '27123456789' }]
  }
}];

const item = $input.item.json;
const messages = item.messages;
if (!messages || !Array.isArray(messages) || messages.length === 0) {
  return [];
}
const m = messages[0];
if (m.type !== 'text' || !m.text || !m.text.body) {
  return [];
}
const waFrom = String(m.from || '').replace(/\D/g, '') || String(m.from || '');
let fromName = '';
const contacts = item.contacts;
if (contacts && Array.isArray(contacts) && contacts.length > 0 && contacts[0].profile) {
  fromName = String(contacts[0].profile.name || '');
}
const ts = m.timestamp ? parseInt(String(m.timestamp), 10) : Math.floor(Date.now() / 1000);
const date = new Date(ts * 1000).toISOString();
return [{
  json: {
    wa_from: waFrom,
    from_name: fromName,
    subject: '',
    body: String(m.text.body).trim().substring(0, 8000),
    date,
    raw: item
  }
}];

const raw = $input.item.json;
const emb = raw.embedding || (raw.body && raw.body.embedding);
if (!Array.isArray(emb)) throw new Error('Ollama response missing embedding array');
const p = $('Parse WhatsApp').item.json;
const cid = $env.CLIENT_ID;
const collection = (cid && String(cid).trim()) ? String(cid).trim() : 'demo_client';
return [{ json: {
  wa_from: p.wa_from,
  from_name: p.from_name,
  subject: p.subject,
  body: p.body,
  date: p.date,
  query_embedding: emb,
  collection,
  chat_model: $env.LLAMA_CHAT_MODEL,
  qdrant_url: $env.QDRANT_URL,
  llama_url: $env.LLAMA_SERVER_URL
} }];

const d = $input.item.json;
const body = {
  query: d.query_embedding,
  limit: 5,
  with_payload: true
};
return [{ json: { ...d, qdrant_request_body: JSON.stringify(body) } }];

const httpOut = $input.item.json;
const merge = $('Merge WhatsApp + Embedding').item.json;
const root = httpOut.body !== undefined ? httpOut.body : httpOut;
const res = root.result !== undefined ? root.result : root;
const points = Array.isArray(res.points) ? res.points : [];
const context = points
  .map((p, i) => '[' + (i + 1) + '] ' + (p.payload && p.payload.text ? String(p.payload.text) : ''))
  .filter((s) => s.length > 4)
  .join('\n\n');
return [{
  json: {
    ...merge,
    context,
    has_rag: points.length > 0,
    rag_hits: points.length
  }
}];

const d = $input.item.json;
const system = 'You are a customer support assistant. Answer ONLY using the CONTEXT block below. If the answer is not in the context, say clearly that you will have a team member follow up shortly. Do not invent hours, prices, or policies. Be concise, warm, and professional. Reply in plain text only. Keep under 4000 characters (WhatsApp text limit).';
const userMsg = 'CONTEXT:\n' + (d.context || '') + '\n\n---\nINBOUND WHATSAPP\nFrom: ' + (d.from_name || '') + ' (' + (d.wa_from || '') + ')\nMessage:\n' + (d.body || '') + '\n\n---\nWrite a helpful reply to the customer.';
const payload = {
  model: d.chat_model,
  temperature: 0.3,
  max_tokens: 1024,
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: userMsg }
  ]
};
return [{ json: { ...d, llm_request_body: JSON.stringify(payload) } }];

const llmOut = $input.item.json;
const ctx = $('Build RAG Context').item.json;
const root = llmOut.body !== undefined ? llmOut.body : llmOut;
const choices = root.choices || [];
const msg = choices[0] && choices[0].message ? choices[0].message : {};
let text = msg.content && String(msg.content).trim() ? String(msg.content).trim() : '';
if (!text && msg.reasoning_content) {
  text = String(msg.reasoning_content).trim();
}
const fallback = 'Thanks for your message! I do not have enough information to answer that automatically. A team member will follow up with you shortly.';
let out = text || fallback;
if (out.length > 4000) out = out.substring(0, 3997) + '...';
return [{
  json: {
    wa_from: ctx.wa_from,
    from_name: ctx.from_name,
    original_subject: ctx.subject,
    reply_text: out
  }
}];
